plc/PLC_1/blocks/10_Drives/Motors/Fx_Mot:
FUNCTION_BLOCK "Fx_Motor"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Start : Bool;
      Stop : Bool;
      SpeedSetpoint : Real;   // rpm
   END_VAR

   VAR_OUTPUT 
      Running : Bool;
      SpeedOut : Real;
   END_VAR

   VAR 
      Latch : Bool;
   END_VAR


BEGIN
	// Überwachung: simple start/stop latch
	#Latch := (#Start OR #Latch) AND NOT #Stop;
	#Running := #Latch;
	IF #Running THEN
	    #SpeedOut := LIMIT(MN := 0.0, IN := #SpeedSetpoint, MX := 3000.0);
	ELSE
	    #SpeedOut := 0.0;
	END_IF;
END_FUNCTION_BLOCK

plc/PLC_1/blocks/10_Drives/Fx_Counter.sc:
FUNCTION_BLOCK "Fx_Counter"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Pulse : Bool;
      Reset : Bool;
   END_VAR

   VAR_OUTPUT 
      Count : DInt;
      Elapsed : Time;
   END_VAR

   VAR 
      Debounce {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
      LastPulse : Bool;
   END_VAR


BEGIN
	#Debounce(IN := #Pulse,
	          PT := T#20ms,
	          ET => #Elapsed);
	IF #Reset THEN
	    #Count := 0;
	ELSIF #Debounce.Q AND NOT #LastPulse THEN
	    #Count := #Count + 1;
	END_IF;
	#LastPulse := #Debounce.Q;
END_FUNCTION_BLOCK

plc/PLC_1/blocks/20_Valves/Fx_Valve.scl:
FUNCTION "Fx_Valve" : Void
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Enable : Bool;
      Mode : Int;
   END_VAR

   VAR_OUTPUT 
      Open : Bool;
   END_VAR


BEGIN
	CASE #Mode OF
	    0:
	        #Open := FALSE;
	    1:
	        #Open := #Enable AND #Enable;
	    ELSE
	        #Open := FALSE;
	END_CASE;
END_FUNCTION

